from collections import deque
def comps(g):
    seen=[[False]*len(g[0]) for _ in g]; res={}
    for i in range(len(g)):
        for j in range(len(g[0])):
            if not seen[i][j]:
                v=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; n=0
                while q:
                    a,b=q.popleft(); n+=1
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<len(g) and 0<=y<len(g[0]) and not seen[x][y] and g[x][y]==v:
                            seen[x][y]=True; q.append((x,y))
                res[v]=res.get(v,0)+1
    return res
